<div class="modal fade" data-backdrop="static" data-dismiss="modal"  id="modal_update_date_ship" tabindex="-1" role="dialog">    <div class="modal-dialog">		<?php echo form_open(admin_url('orders/update_date_ship/' . (!empty($order_id) ? $order_id : '')), array('id' => 'form_update_date_ship')); ?>        <div class="modal-content">            <div class="modal-header">                <button type="button" class="close" data-dismiss="modal" aria-label="Close">                    <span aria-hidden="true">&times;</span>                </button>                <h4 class="modal-title">                    <span class="edit-title"><?php echo !empty($title) ? $title : '' ?></span>                </h4>            </div>            <div class="modal-body">                <div class="col-md-12">                    <?php $value = !empty($date_shipping) ? _d($date_shipping) : ''?>                    <?php echo render_date_input('date_shipping', 'Ngày giao hàng dự kiến', $value);?>                </div>                <div class="clearfix"></div>            </div>            <div class="modal-footer">                <div class="pull-right">                    <button type="submit" class="btn btn-info"><?= _l('Cập nhật') ?></button>                    <button type="button" class="btn btn-default" data-dismiss="modal"><?php echo _l('close'); ?></button>                </div>            </div>        </div>		<?php echo form_close(); ?>    </div></div><script type="text/javascript">    $('#modal_update_date_ship').modal('show');    init_datepicker();    appValidateForm($('#form_update_date_ship'), {        date_shipping: 'required',    }, manage_update_date_ship);    function manage_update_date_ship(form) {        var data = $(form).serializeArray();        var url = form.action;        $.post(url, data, function(result) {            result = JSON.parse(result);            alert_float(result.alert_type, result.message);            if(result.success) {                $('#modal_update_date_ship').modal('hide');            }        })        return false;    }</script>